fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

@JvmName("step00")
fun step00(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 5
}
sealed class Outcome01 {
    data class Success(val payload: String) : Outcome01()
    data object Failure : Outcome01()
}

fun describe01(outcome: Outcome01): String = when (outcome) {
    is Outcome01.Success -> outcome.payload
    Outcome01.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked02(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
